// Probe floor/ceil default-tolerance expressions for Number and BigNumber
import { create, all } from './src/defaultInstance.js';
const math = create(all);
const { floor, ceil, multiply, pi, pow, bignumber } = math;
function toFixed(x){
  // mathjs BigNumber/stringifies; for Number use Math.trunc-style then as string
  if (typeof x === 'number') return String(x);
  if (x && typeof x.toFixed === 'function') return x.toFixed();
  return String(x);
}

const exprs = [
  {name: "floor(1234567890123.5)", val: floor(1234567890123.5)},
  {name: "ceil(1234567890123.4)", val: ceil(1234567890123.4)},
  {name: "floor(bignumber('12345678901234567890.5')).toFixed()", val: floor(bignumber('12345678901234567890.5')).toFixed()},
  {name: "ceil(bignumber('12345678901234567890.4')).toFixed()", val: ceil(bignumber('12345678901234567890.4')).toFixed()},
  {name: "math.floor(math.multiply(math.pi, math.pow(math.bignumber(10), math.bignumber(60)))).toFixed()", val: floor(multiply(pi, pow(bignumber(10), bignumber(60)))).toFixed()},
];
for (const e of exprs){
  probe(e.name, e.val);
}

